    def test_collectfile_ignores_duplicate_paths(self, pytester: Pytester) -> None:
        """Test that _collectfile ignores duplicate paths when keepduplicates is False."""
        pytester.makepyfile(
            """
            def test_func1():
                pass
            def test_func2():
                pass
            """
        )
        config = pytester.config
        config.setoption("keepduplicates", False)
        package = pytester.makepyfile(
            """
            import pytest
            class Package:
                def __init__(self, path):
                    self.path = path
                def _collectfile(self, fspath, handle_dupes=True):
                    return [pytest.Item(fspath, self)]
            package = Package(".")
            """
        )
        package_obj = package.getitem("package")
        fspath = package.path
        result = package_obj._collectfile(fspath)
        assert len(result) == 1

        # Simulate duplicate path collection
        package_obj._collectfile(fspath)
        result = package_obj._collectfile(fspath)
        assert len(result) == 0
