    def _create_metafunc(self, func_code: str) -> Metafunc:
        """Helper function to create a Metafunc instance for testing."""
        from _pytest.python import Function
        from _pytest.fixtures import FuncFixtureInfo

        func = eval(func_code)
        item = Function.from_parent(self, name="test_func", obj=func)
        fixtureinfo = FuncFixtureInfo(item, {})
        return Metafunc(
            definition=item,
            fixtureinfo=fixtureinfo,
            config=self.config,
            cls=None,
            module=None,
        )
