@pytest.mark.parametrize("norm_type, boundaries, expected_locator", [
    (Normalize, None, None),
    (BoundaryNorm, [0, 1, 2, 3], FixedLocator([0, 1, 2, 3])),
    (NoNorm, None, None),
    (LogNorm, [1, 10, 100], FixedLocator([1, 10, 100])),
    (BoundaryNorm, [0, 1, 2, 3], FixedLocator([0, 1, 2, 3])),
])
def test_colorbar_get_ticker_locator_formatter(norm_type, boundaries, expected_locator):
    """Test the _get_ticker_locator_formatter method."""
    fig, ax = plt.subplots()
    if boundaries is not None:
        norm = norm_type(boundaries=boundaries)
    else:
        norm = norm_type()
    cbar = Colorbar(ax, cmap='viridis', norm=norm)
    locator = cbar._locator
    if expected_locator is None:
        assert locator is None
    else:
        assert isinstance(locator, expected_locator)
