@pytest.mark.parametrize("norm_type, expected_scale", [
    ("Normalize", "linear"),
    ("LogNorm", "log"),
    ("PowerNorm", "linear"),
    ("BoundaryNorm", "uniform"),
    ("NoNorm", "linear"),
])
def test_colorbar_reset_locator_formatter_scale(norm_type, expected_scale):
    """Test that the correct scale is set based on the norm type."""
    fig, ax = plt.subplots()
    if norm_type == "Normalize":
        norm = mcolors.Normalize(vmin=0, vmax=10)
    elif norm_type == "LogNorm":
        norm = mcolors.LogNorm(vmin=1, vmax=100)
    elif norm_type == "PowerNorm":
        norm = mcolors.PowerNorm(gamma=0.5, vmin=0, vmax=1)
    elif norm_type == "BoundaryNorm":
        bounds = [0, 1, 2, 3, 4, 5]
        norm = mcolors.BoundaryNorm(bounds, len(bounds) - 1)
    elif norm_type == "NoNorm":
        norm = mcolors.NoNorm()
    else:
        raise ValueError(f"Unknown norm type: {norm_type}")

    cbar = Colorbar(ax, cmap=plt.cm.viridis, norm=norm)
    assert cbar._long_axis().get_scale() == expected_scale
