def test_itermonomials_edge_cases():
    """Test edge cases for itermonomials."""
    assert set(itermonomials([x, y], [0, 0], [0, 0])) == {S.One}
    assert set(itermonomials([x, y], [0, 0], [1, 1])) == set()
    assert set(itermonomials([x, y], [1, 1], [0, 0])) == {S.One, x, y, x*y}
    assert set(itermonomials([x, y], [1, 1], [1, 1])) == {x, y, x*y}
    assert set(itermonomials([x, y], [2, 2], [1, 1])) == {x, y, x*y, x**2, y**2, x**2*y, x*y**2}
    assert set(itermonomials([x, y], [2, 2], [2, 2])) == {x**2, y**2, x**2*y, x*y**2}
    assert set(itermonomials([x, y], [3, 3], [1, 1])) == {x, y, x*y, x**2, y**2, x**2*y, x*y**2, x**3, y**3, x**3*y, x*y**3, x**2*y**2}
    assert set(itermonomials([x, y], [3, 3], [2, 2])) == {x**2, y**2, x**2*y, x*y**2, x**3, y**3, x**3*y, x*y**3, x**2*y**2}
    assert set(itermonomials([x, y], [3, 3], [3, 3])) == {x**3, y**3, x**3*y, x*y**3, x**2*y**2}
    assert set(itermonomials([x, y], [1, 0], [0, 0])) == {S.One, x}
    assert set(itermonomials([x, y], [0, 1], [0, 0])) == {S.One, y}
    assert set(itermonomials([x, y], [1, 0], [1, 0])) == {x}
    assert set(itermonomials([x, y], [0, 1], [0, 1])) == {y}
    assert set(itermonomials([x, y], [1, 1], [0, 1])) == {y, x*y}
    assert set(itermonomials([x, y], [1, 1], [1, 0])) == {x, x*y}
    assert set(itermonomials([x, y], [2, 2], [1, 1])) == {x, y, x*y, x**2, y**2, x**2*y, x*y**2}
    assert set(itermonomials([x, y], [2, 2], [2, 2])) == {x**2, y**2, x**2*y, x*y**2}
    assert set(itermonomials([x, y], [2, 2], [0, 0])) == {S.One, x, y, x**2, y**2, x*y}
