def test_process_projection_requirements():
    """Test the _process_projection_requirements method."""
    from matplotlib import projections
    from matplotlib.projections import PolarAxes

    # Test case 1: No arguments, default projection
    projection_class, proj_kwargs = FigureBase._process_projection_requirements(
        None, None, None
    )
    assert projection_class is projections.get_projection_class(None)
    assert proj_kwargs == {}

    # Test case 2: String projection
    projection_class, proj_kwargs = FigureBase._process_projection_requirements(
        None, None, "polar"
    )
    assert projection_class is projections.get_projection_class("polar")
    assert proj_kwargs == {}

    # Test case 3: Polar flag
    projection_class, proj_kwargs = FigureBase._process_projection_requirements(
        None, None, polar=True
    )
    assert projection_class is projections.get_projection_class("polar")
    assert proj_kwargs == {}

    # Test case 4: Custom projection class
    class CustomProjection:
        pass

    projection_class, proj_kwargs = FigureBase._process_projection_requirements(
        None, None, axes_class=CustomProjection
    )
    assert projection_class is CustomProjection
    assert proj_kwargs == {}

    # Test case 5: Invalid combination of arguments
    with pytest.raises(ValueError):
        FigureBase._process_projection_requirements(
            None, None, polar=True, projection="rectilinear"
        )

    # Test case 6: axes_class and kwargs
    class CustomProjectionWithKwargs:
        def __init__(self, **kwargs):
            self.kwarg1 = kwargs.get("kwarg1")

    projection_class, proj_kwargs = FigureBase._process_projection_requirements(
        None, None, axes_class=CustomProjectionWithKwargs, kwarg1="value1"
    )
    assert projection_class is CustomProjectionWithKwargs
    assert proj_kwargs == {"kwarg1": "value1"}

    # Test case 7: projection and kwargs
    projection_class, proj_kwargs = FigureBase._process_projection_requirements(
        None, None, projection="polar", kwarg1="value1"
    )
    assert projection_class is projections.get_projection_class("polar")
    assert proj_kwargs == {"kwarg1": "value1"}

    # Test case 8: projection class with _as_mpl_axes
    class ProjectionWithAsMplAxes:
        def _as_mpl_axes(self):
            return PolarAxes, {"extra_kwarg": "extra_value"}

    projection_class, proj_kwargs = FigureBase._process_projection_requirements(
        None, None, projection=ProjectionWithAsMplAxes()
    )
    assert projection_class is PolarAxes
    assert proj_kwargs == {"extra_kwarg": "extra_value"}
