def test_canonical_variables_complex():
    """Test canonical_variables with more complex expressions."""
    x, y, z = symbols('x y z')
    assert Integral(x, (x, 1, 2)).canonical_variables == {x: symbols('_0')}
    assert Integral(x**2, (x, 1, 2)).canonical_variables == {x: symbols('_0')}
    assert Derivative(x**2, x).canonical_variables == {x: symbols('_0')}
    assert Derivative(x**2 + y, x).canonical_variables == {x: symbols('_0')}
    assert Derivative(x**2 + y, y).canonical_variables == {y: symbols('_0')}
    assert Sum(x, (x, 1, 5)).canonical_variables == {x: symbols('_0')}
    assert Sum(x**2, (x, 1, 5)).canonical_variables == {x: symbols('_0')}
    assert Integral(x, (y, 1, 2)).canonical_variables == {y: symbols('_0')}
    assert Integral(x, (x, y, z)).canonical_variables == {x: symbols('_0'), y: symbols('_1')}
    assert Integral(x, (x, y, z)).canonical_variables == {x: symbols('_0'), y: symbols('_1')}
    assert Integral(x, (x, Integral(y, (y, 1, 2)), z)).canonical_variables == {x: symbols('_0'), y: symbols('_1')}
