def test_matches_complex():
    """Test more complex matching scenarios."""
    from sympy import Wild, sin, cos, exp, Symbol
    x, y, z = symbols('x y z')
    a, b, c = Wild('a'), Wild('b'), Wild('c')

    # Test with a simple pattern
    assert Basic(x + y).matches(Basic(a + b)) == {a: x, b: y}

    # Test with a more complex pattern
    assert Basic(x**2 + y).matches(Basic(a**2 + b)) == {a: x, b: y}

    # Test with a pattern that doesn't match
    assert Basic(x + y).matches(Basic(a**2 + b)) is None

    # Test with a function application
    assert Basic(sin(x)).matches(Basic(sin(a))) == {a: x}

    # Test with nested function applications
    assert Basic(sin(x + y)).matches(Basic(sin(a + b))) == {a: x, b: y}

    # Test with multiple Wilds
    assert Basic(x * y + z).matches(Basic(a * b + c)) == {a: x, b: y, c: z}

    # Test with a pattern that has more Wilds than arguments
    assert Basic(x + y).matches(Basic(a + b + c)) is None

    # Test with a pattern that has fewer Wilds than arguments
    assert Basic(x + y + z).matches(Basic(a + b)) is None

    # Test with a pattern that includes a function and a symbol
    assert Basic(exp(x) + y).matches(Basic(exp(a) + b)) == {a: x, b: y}

    # Test with a pattern that includes a power
    assert Basic(x**y).matches(Basic(a**b)) == {a: x, b: y}

    # Test with a pattern that includes a product
    assert Basic(x * y * z).matches(Basic(a * b * c)) == {a: x, b: y, c: z}

    # Test with a pattern that includes a sum
    assert Basic(x + y + z).matches(Basic(a + b + c)) == {a: x, b: y, c: z}

    # Test with a pattern that includes a function and a power
    assert Basic(sin(x**y)).matches(Basic(sin(a**b))) == {a: x, b: y}

    # Test with a pattern that includes a function and a product
    assert Basic(sin(x * y)).matches(Basic(sin(a * b))) == {a: x, b: y}

    # Test with a pattern that includes a function and a sum
    assert Basic(sin(x + y)).matches(Basic(sin(a + b))) == {a: x, b: y}

    # Test with a pattern that includes a power and a product
    assert Basic(x**y * z).matches(Basic(a**b * c)) == {a: x, b: y, c: z}

    # Test with a pattern that includes a power and a sum
    assert Basic(x**y + z).matches(Basic(a**b + c)) == {a: x, b: y, c: z}

    # Test with a pattern that includes a product and a sum
    assert Basic(x * y + z).matches(Basic(a * b + c)) == {a: x, b: y, c: z}
