def test_eval_rewrite():
    from sympy import exp, sin, cos, tan, I
    from sympy.abc import x, y
    class MyBasic(Basic):
        def _eval_rewrite_as_exp(self, arg):
            return exp(arg)
        def _eval_rewrite_as_sin(self, arg):
            return sin(arg)

    b = MyBasic(x)
    assert b.rewrite(exp) == exp(x)
    assert b.rewrite(sin) == sin(x)
    assert b.rewrite([exp, sin]) == exp(x)

    assert b._eval_rewrite(None, '_eval_rewrite_as_exp') == exp(x)
    assert b._eval_rewrite(None, '_eval_rewrite_as_sin') == sin(x)

    assert b.rewrite(exp, deep=False) == exp(x)
    assert b.rewrite(sin, deep=False) == sin(x)

    class MyAtom(Atom):
        def _eval_rewrite_as_exp(self):
            return exp(self.args[0])

    a = MyAtom(x)
    assert a.rewrite(exp) == exp(x)
    assert a._eval_rewrite(None, '_eval_rewrite_as_exp') == exp(x)

    assert Basic(sin(x)).rewrite(sin) == sin(x)
    assert Basic(sin(x))._eval_rewrite(None, '_eval_rewrite_as_sin') == sin(x)

    assert Basic(x + y).rewrite(sin) == x + y
    assert Basic(x + y)._eval_rewrite(None, '_eval_rewrite_as_sin') == x + y

    assert Basic(I).rewrite(exp) == I
    assert Basic(I)._eval_rewrite(None, '_eval_rewrite_as_exp') == I
