def test_constructor_postprocessors():
    """Test the constructor postprocessors."""
    from sympy import Symbol
    from sympy.core.basic import Basic

    class MyClass(Basic):
        pass

    Basic._constructor_postprocessor_mapping[MyClass] = {
        'args': [lambda args: [arg + 1 for arg in args]]
    }

    instance = MyClass(1, 2)
    assert instance.args == (2, 3)

    Basic._constructor_postprocessor_mapping.clear()

    class AnotherClass(Basic):
        pass

    Basic._constructor_postprocessor_mapping[AnotherClass] = {
        'args': [lambda args: [Symbol('x') for _ in args]]
    }

    instance = AnotherClass(1, 2)
    assert instance.args == (Symbol('x'), Symbol('x'))

    Basic._constructor_postprocessor_mapping.clear()
