def test_FunctionClass_init_nargs():
    from sympy import Function
    # Test with valid nargs values
    f1 = Function('f', nargs=1)
    assert f1.nargs == {1}
    f2 = Function('f', nargs=(1, 2))
    assert f2.nargs == {1, 2}
    f3 = Function('f', nargs=None)
    assert f3.nargs == set()
    # Test with invalid nargs values
    try:
        Function('f', nargs=[])
        assert False, "Should have raised ValueError"
    except ValueError:
        pass
    # Test with nargs inherited from a subclass
    class MyFunction(Function):
        nargs = 2
    f4 = MyFunction('g')
    assert f4.nargs == {2}
    # Test with kwargs overriding class-defined nargs
    class MyFunction2(Function):
        nargs = (1, 2)
    f5 = MyFunction2('h', nargs=3)
    assert f5.nargs == {3}
    # Test with kwargs and inherited nargs
    class MyFunction3(Function):
        nargs = (1, 2)
    f6 = MyFunction3('i', nargs=(2, 3))
    assert f6.nargs == {2, 3}
